233	type balanceKey struct {
234		account string
235		asset   string
236	}
237	
238	type ledgerState struct {
239		Version     int
240		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
241		Balances    map[balanceKey]int64 // 当前余额
242		Settlements []Record
243		Refunds     []RefundRecord
244	}
