246	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
247	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
248	// 且无退款的账本写回时继续省略该字段。
249	type unsignedDoc struct {
250		Version     int            `json:"version"`
251		Initial     []BalanceView  `json:"initial_balances"`
252		Balances    []BalanceView  `json:"balances"`
253		Settlements []Record       `json:"settlements"`
254		Refunds     []RefundRecord `json:"refunds,omitempty"`
255	}
256	
257	type signedDoc struct {
258		unsignedDoc
259		Checksum string `json:"checksum"`
260	}
261	
262	func balanceList(m map[balanceKey]int64) []BalanceView {
263		out := make([]BalanceView, 0, len(m))
264		for k, v := range m {
265			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
266		}
267		sortBalances(out)
268		return out
269	}
270	
271	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
272		out := make(map[balanceKey]int64, len(list))
273		for i, b := range list {
274			if b.Account == "" || b.Asset == "" {
275				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
276			}
277			if b.Balance < 0 {
278				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
279			}
280			k := balanceKey{b.Account, b.Asset}
281			if _, dup := out[k]; dup {
282				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
283			}
284			out[k] = b.Balance
285		}
286		return out, nil
287	}
288	
289	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
290	func (s *ledgerState) MarshalJSON() ([]byte, error) {
291		settlements := s.Settlements
292		if settlements == nil {
293			settlements = []Record{}
294		}
295		doc := unsignedDoc{
296			Version:     s.Version,
297			Initial:     balanceList(s.Initial),
298			Balances:    balanceList(s.Balances),
299			Settlements: settlements,
300			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
301		}
302		payload, err := json.Marshal(doc)
303		if err != nil {
304			return nil, err
305		}
306		sum := checksumHex(payload)
307		out := make([]byte, 0, len(payload)+len(sum)+16)
308		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
309		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
310		return out, nil
311	}
312	
313	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
314	func (s *ledgerState) UnmarshalJSON(data []byte) error {
315		var doc signedDoc
316		if err := json.Unmarshal(data, &doc); err != nil {
317			return err
318		}
319		if doc.Checksum == "" {
320			return ledgerError(ErrCorrupt, "missing checksum")
321		}
322		payload, err := json.Marshal(doc.unsignedDoc)
323		if err != nil {
324			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
325		}
326		if got := checksumHex(payload); got != doc.Checksum {
327			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
328		}
329		if doc.Version != ledgerVersion {
330			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
331		}
332		initial, err := balanceMap(doc.Initial)
333		if err != nil {
334			return err
335		}
336		current, err := balanceMap(doc.Balances)
337		if err != nil {
338			return err
339		}
340		records := doc.Settlements
341		if records == nil {
342			records = []Record{}
343		}
344		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
345		if refunds == nil {
346			refunds = []RefundRecord{}
347		}
348		if err := validateAndReplay(initial, current, records, refunds); err != nil {
349			return err
350		}
351		s.Version = doc.Version
352		s.Initial = initial
353		s.Balances = current
354		s.Settlements = records
355		s.Refunds = refunds
356		return nil
357	}
358	
359	func decodeState(data []byte) (*ledgerState, error) {
360		var state ledgerState
361		if err := json.Unmarshal(data, &state); err != nil {
362			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
363				return nil, err
364			}
365			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
366		}
367		return &state, nil
368	}
369	
370	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
371	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
372	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
373	func CreateLedger(path string, init []BalanceInit) error {
374		if err := validateInitial(init); err != nil {
375			return err
376		}
377		abs, err := filepath.Abs(path)
378		if err != nil {
379			return ledgerError(ErrStorage, "resolve path: %v", err)
380		}
381	
382		openMu.Lock()
383		defer openMu.Unlock()
384	
385		if _, err := os.Stat(abs); err == nil {
386			return ledgerError(ErrExists, "ledger already exists at %s", abs)
387		} else if !errors.Is(err, os.ErrNotExist) {
388			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
389		}
390		if openRegistry[abs] != nil {
391			return ledgerError(ErrExists, "ledger is already initialized in this process")
392		}
393	
394		state := &ledgerState{
395			Version:     ledgerVersion,
396			Initial:     make(map[balanceKey]int64, len(init)),
397			Balances:    make(map[balanceKey]int64, len(init)),
398			Settlements: []Record{},
399			Refunds:     []RefundRecord{},
400		}
401		for _, b := range init {
402			k := balanceKey{b.Account, b.Asset}
403			state.Initial[k] = b.Balance
404			state.Balances[k] = b.Balance
405		}
406		if err := atomicWrite(abs, state); err != nil {
407			return err
408		}
409		openRegistry[abs] = &registryEntry{state: state}
410		return nil
411	}
412	
413	func validateInitial(init []BalanceInit) error {
414		seen := map[balanceKey]bool{}
415		for i, b := range init {
416			if b.Account == "" {
417				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
418			}
419			if b.Asset == "" {
420				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
421			}
422			if b.Balance < 0 {
423				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
424			}
425			k := balanceKey{b.Account, b.Asset}
426			if seen[k] {
427				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
428			}
429			seen[k] = true
430		}
431		return nil
432	}
433	
434	// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
435	// 返回共享同一状态与互斥锁的实例，因此并发提交按同一本账本串行化。
436	type Ledger struct {
437		path string
438		reg  *registryEntry
439		open bool
440	}
441	
442	type registryEntry struct {
443		mu       sync.Mutex // 保护 state；整个批次串行持有
444		state    *ledgerState
445		refs     int        // 打开的句柄数
446		ops      int        // 正在执行的 Submit/Query 数
447		failHook FailWriter // 仅测试注入
448	}
449	
450	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
451	// 调用方必须持有 openMu。
452	func tryEvict(path string, reg *registryEntry) {
453		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
454			delete(openRegistry, path)
455		}
456	}
457	
458	var (
459		openMu       sync.Mutex
460		openRegistry = map[string]*registryEntry{}
461	)
462	
463	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
464	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
465	func Open(path string) (*Ledger, error) {
466		abs, err := filepath.Abs(path)
467		if err != nil {
468			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
469		}
470	
471		openMu.Lock()
472		defer openMu.Unlock()
473	
474		if reg := openRegistry[abs]; reg != nil {
475			reg.refs++
476			return &Ledger{path: abs, reg: reg, open: true}, nil
477		}
478	
479		data, err := os.ReadFile(abs)
480		if err != nil {
481			if errors.Is(err, os.ErrNotExist) {
482				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
483			}
484			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
485		}
486		if len(bytes.TrimSpace(data)) == 0 {
487			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
488		}
489		dec := json.NewDecoder(bytes.NewReader(data))
490		var rawDoc json.RawMessage
491		if err := dec.Decode(&rawDoc); err != nil {
492			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
493		}
494		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
495		if tok, err := dec.Token(); err != io.EOF {
496			if err == nil {
497				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
498			}
499			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
500		}
501		state, err := decodeState(rawDoc)
502		if err != nil {
503			return nil, err
504		}
505	
506		reg := &registryEntry{state: state, refs: 1}
507		openRegistry[abs] = reg
508		return &Ledger{path: abs, reg: reg, open: true}, nil
509	}
510	
511	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
512	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
513	// 从磁盘重新加载而丢失正在写入的状态。
514	func (l *Ledger) Close() error {
515		openMu.Lock()
516		defer openMu.Unlock()
517		if !l.open {
518			return nil
519		}
520		l.open = false
521		l.reg.refs--
522		tryEvict(l.path, l.reg)
523		return nil
524	}
525	
526	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
527	func (l *Ledger) beginOp() error {
528		openMu.Lock()
529		defer openMu.Unlock()
530		if !l.open {
531			return ledgerError(ErrClosed, "ledger handle is closed")
532		}
533		l.reg.ops++
534		return nil
535	}
536	
537	func (l *Ledger) endOp() {
538		openMu.Lock()
539		defer openMu.Unlock()
540		l.reg.ops--
541		tryEvict(l.path, l.reg)
542	}
543	
544	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
545	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
546	// 拆成商和余数两部分即可在 int64 内精确完成。
547	func feeFor(amount int64, feeBps int) int64 {
548		hi := amount / 10000
549		lo := amount % 10000
550		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
551	}
552	
553	func validateIntent(it PaymentIntent) (int64, string, bool) {
554		if it.ID == "" {
555			return 0, reasonEmptyID, false
556		}
557		if it.Account == "" {
558			return 0, reasonEmptyAccount, false
559		}
560		if it.Asset == "" {
561			return 0, reasonEmptyAsset, false
562		}
563		if it.Amount == nil || *it.Amount <= 0 {
564			return 0, reasonBadAmount, false
565		}
566		return *it.Amount, "", true
567	}
568	
569	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
570	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
571	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
572	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
573		if len(limits) == 0 {
574			return nil, nil
575		}
576		out := make(map[balanceKey]int64, len(limits))
577		for i, l := range limits {
578			if l.Account == "" {
579				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
580			}
581			if l.Asset == "" {
582				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
583			}
584			if l.MaxCharged == nil {
585				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
586			}
587			if *l.MaxCharged < 0 {
588				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
589			}
590			k := balanceKey{l.Account, l.Asset}
591			if _, dup := out[k]; dup {
592				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
593			}
594			out[k] = *l.MaxCharged
595		}
596		return out, nil
597	}
598	
599	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
600	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
601	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
602	//
603	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
604	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
605	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
606	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
607	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
608		if err := l.beginOp(); err != nil {
609			return nil, err
610		}
611		defer l.endOp()
612		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
613			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
614		}
615		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
616		limits, err := validateLimits(batch.Limits)
617		if err != nil {
618			return nil, err
619		}
620		out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
621	
622		l.reg.mu.Lock()
623		defer l.reg.mu.Unlock()
624	
625		// 本次提交内各组合已消耗的额度，从零开始，仅成功落账的扣款计入。
626		used := make(map[balanceKey]int64, len(limits))
627	
628		for i := range batch.Intents {
629			it := &batch.Intents[i]
630			res := ItemResult{ID: it.ID}
631	
632			// 1. 参数校验。未通过的编号不占用去重资格。
633			amount, reason, ok := validateIntent(*it)
634			if !ok {
635				res.Status = StatusInvalid
636				res.Reason = reason
637				out.Results = append(out.Results, res)
638				continue
639			}
640	
641			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
642			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
643			//    本批次内先成功的同编号项也在此被看到。
644			if rec, exists := l.findRecord(it.ID); exists {
645				if sameRequest(rec, it, amount, batch.FeeBps) {
646					cp := rec
647					res.Status = StatusDuplicate
648					res.Reason = reasonDuplicate
649					res.Record = &cp
650				} else {
651					res.Status = StatusConflict
652					res.Reason = reasonConflict
653				}
654				out.Results = append(out.Results, res)
655				continue
656			}
657	
658			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
659			if it.State != "" && it.State != "pending" {
660				res.Status = StatusState
661				res.Reason = reasonNotPending
662				out.Results = append(out.Results, res)
663				continue
664			}
665	
666			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
667			fee := feeFor(amount, batch.FeeBps)
668			if fee > math.MaxInt64-amount {
669				res.Status = StatusInvalid
670				res.Reason = reasonOverflow
671				out.Results = append(out.Results, res)
672				continue
673			}
674			total := amount + fee
675	
676			key := balanceKey{it.Account, it.Asset}
677	
678			// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
679			//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
680			//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
681			if max, capped := limits[key]; capped {
682				if u := used[key]; total > max-u {
683					res.Status = StatusLimitExceeded
684					res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
685					out.Results = append(out.Results, res)
686					continue
687				}
688			}
689	
690			// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
691			bal := l.reg.state.Balances[key]
692			if total > bal {
693				res.Status = StatusFunds
694				res.Reason = reasonFunds
695				out.Results = append(out.Results, res)
696				continue
697			}
698	
699			// 7. 先在内存生效，再原子持久化；保存失败回滚该项，不留成功记录。
700			rec := Record{
701				ID:        it.ID,
702				Account:   it.Account,
703				Paymaster: it.Paymaster,
704				Asset:     it.Asset,
705				Amount:    amount,
706				Nonce:     it.Nonce,
707				FeeBps:    batch.FeeBps,
708				Fee:       fee,
709				Charged:   total,
710				Seq:       int64(len(l.reg.state.Settlements)) + 1,
711			}
712			rollback := l.stage(key, bal-total, rec)
713			if err := l.persistLocked(); err != nil {
714				rollback()
715				res.Status = StatusStorage
716				res.Reason = err.Error()
717			} else {
718				// 只有成功落账的扣款消耗额度；保存失败回滚后额度自然未占用。
719				used[key] += total
720				cp := rec
721				res.Status = StatusSettled
722				res.Record = &cp
723			}
724			out.Results = append(out.Results, res)
725		}
726		return out, nil
727	}
728	
729	// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
730	func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
731		oldBal, hadKey := l.reg.state.Balances[key]
732		oldLen := len(l.reg.state.Settlements)
733		l.reg.state.Balances[key] = newBal
734		l.reg.state.Settlements = append(l.reg.state.Settlements, rec)
735		return func() {
736			if hadKey {
737				l.reg.state.Balances[key] = oldBal
738			} else {
739				delete(l.reg.state.Balances, key)
740			}
741			l.reg.state.Settlements = l.reg.state.Settlements[:oldLen]
742		}
743	}
744	
745	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
746	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
747	// 结果与输入逐项对应，空批次返回空结果。
748	//
749	// 语义：
750	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
751	//     及原退款记录（不再入账）；任一不同返回 conflict。
752	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
753	//     该结算已被其他退款编号退回返回 refunded，不增加余额。
754	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
755	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
756	//   - 失败申请不占用退款编号，之后可修改原因或目标再提交。
757	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
758		if err := l.beginOp(); err != nil {
759			return nil, err
760		}
761		defer l.endOp()
762		out := &RefundBatchResult{Results: make([]RefundResult, 0, len(batch.Refunds))}
763	
764		l.reg.mu.Lock()
765		defer l.reg.mu.Unlock()
766	
767		for i := range batch.Refunds {
768			req := &batch.Refunds[i]
769			res := RefundResult{ID: req.ID}
770	
771			// 1. 参数校验：退款编号、原付款编号、原因三者都必须非空。
772			//    未通过的编号不占用退款资格。
773			if req.ID == "" {
774				res.Status = StatusInvalid
775				res.Reason = reasonEmptyRefundID
776				out.Results = append(out.Results, res)
777				continue
778			}
779			if req.SettlementID == "" {
780				res.Status = StatusInvalid
781				res.Reason = reasonEmptySettlement
782				out.Results = append(out.Results, res)
783				continue
784			}
785			if req.Reason == "" {
786				res.Status = StatusInvalid
787				res.Reason = reasonEmptyReason
788				out.Results = append(out.Results, res)
789				continue
790			}
791	
792			// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
793			//    任一不同则冲突。两者都不再入账。本批次内先成功的同编号项也在此可见。
794			if prior, exists := l.findRefund(req.ID); exists {
795				if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
796					cp := prior
797					res.Status = StatusDuplicate
798					res.Reason = prior.Reason
799					res.SettlementID = prior.SettlementID
800					res.Account = prior.Account
801					res.Asset = prior.Asset
802					res.Charged = prior.Charged
803					res.Record = &cp
804				} else {
805					res.Status = StatusConflict
806					res.Reason = reasonRefundConflict
807				}
808				out.Results = append(out.Results, res)
809				continue
810			}
811	
812			// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
813			target, exists := l.findRecord(req.SettlementID)
814			if !exists {
815				res.Status = StatusNotFound
816				res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
817				out.Results = append(out.Results, res)
818				continue
819			}
820	
821			// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
822			if prior, refunded := l.findRefundOfSettlement(req.SettlementID); refunded {
823				res.Status = StatusAlreadyRefunded
824				res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
825				out.Results = append(out.Results, res)
826				continue
827			}
828	
829			// 5. 全额退回原账户、原资产（amount 与当时手续费一并退回），
830			//    与退款记录在同一个原子写入中落盘；保存失败回滚该项。
831			rec := RefundRecord{
832				ID:           req.ID,
833				SettlementID: target.ID,
834				Reason:       req.Reason,
835				Account:      target.Account,
836				Asset:        target.Asset,
837				Amount:       target.Amount,
838				Fee:          target.Fee,
839				Charged:      target.Charged,
840				AfterSeq:     int64(len(l.reg.state.Settlements)),
841				Seq:          int64(len(l.reg.state.Refunds)) + 1,
842			}
843			key := balanceKey{target.Account, target.Asset}
844			bal := l.reg.state.Balances[key]
845			rollback := l.stageRefund(key, bal+target.Charged, rec)
846			if err := l.persistLocked(); err != nil {
847				rollback()
848				res.Status = StatusStorage
849				res.Reason = err.Error()
850			} else {
851				cp := rec
852				res.Status = StatusRefundSuccess
853				res.Reason = rec.Reason
854				res.SettlementID = rec.SettlementID
855				res.Account = rec.Account
856				res.Asset = rec.Asset
857				res.Charged = rec.Charged
858				res.Record = &cp
859			}
860			out.Results = append(out.Results, res)
861		}
862		return out, nil
863	}
864	
865	// stageRefund 应用一笔退款（余额增加 + 记录追加），返回回滚函数。
866	func (l *Ledger) stageRefund(key balanceKey, newBal int64, rec RefundRecord) func() {
867		oldBal, hadKey := l.reg.state.Balances[key]
868		oldLen := len(l.reg.state.Refunds)
869		l.reg.state.Balances[key] = newBal
870		l.reg.state.Refunds = append(l.reg.state.Refunds, rec)
871		return func() {
872			if hadKey {
873				l.reg.state.Balances[key] = oldBal
874			} else {
875				delete(l.reg.state.Balances, key)
876			}
877			l.reg.state.Refunds = l.reg.state.Refunds[:oldLen]
878		}
879	}
880	
881	func (l *Ledger) findRefund(id string) (RefundRecord, bool) {
882		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
883		for _, r := range l.stateView().Refunds {
884			if r.ID == id {
885				return r, true
886			}
887		}
888		return RefundRecord{}, false
889	}
890	
891	// findRefundOfSettlement 返回退回指定结算的那笔退款（每笔结算最多一笔）。
892	func (l *Ledger) findRefundOfSettlement(settlementID string) (RefundRecord, bool) {
893		for _, r := range l.stateView().Refunds {
894			if r.SettlementID == settlementID {
895				return r, true
896			}
897		}
898		return RefundRecord{}, false
899	}
900	
901	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
902	
903	func (l *Ledger) findRecord(id string) (Record, bool) {
904		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
905		for _, r := range l.stateView().Settlements {
906			if r.ID == id {
907				return r, true
908			}
909		}
910		return Record{}, false
911	}
912	
913	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
914	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
915		return r.Account == it.Account &&
916			r.Paymaster == it.Paymaster &&
917			r.Asset == it.Asset &&
918			r.Amount == amount &&
919			r.Nonce == it.Nonce &&
920			r.FeeBps == feeBps
921	}
922	
923	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
924	func (l *Ledger) Query() (*Snapshot, error) {
925		if err := l.beginOp(); err != nil {
926			return nil, err
927		}
928		defer l.endOp()
929		l.reg.mu.Lock()
930		defer l.reg.mu.Unlock()
931	
932		st := l.stateView()
933		bals := make([]BalanceView, 0, len(st.Balances))
934		for k, v := range st.Balances {
935			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
936		}
937		sortBalances(bals)
938		recs := make([]Record, len(st.Settlements))
939		copy(recs, st.Settlements)
940		refunds := make([]RefundRecord, len(st.Refunds))
941		copy(refunds, st.Refunds)
942		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
943	}
944	
945	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
946	func (l *Ledger) Balance(account, asset string) (int64, error) {
947		if err := l.beginOp(); err != nil {
948			return 0, err
949		}
950		defer l.endOp()
951		l.reg.mu.Lock()
952		defer l.reg.mu.Unlock()
953		return l.stateView().Balances[balanceKey{account, asset}], nil
954	}
955	
956	func sortBalances(bals []BalanceView) {
957		sort.Slice(bals, func(i, j int) bool {
958			if bals[i].Account != bals[j].Account {
959				return bals[i].Account < bals[j].Account
960			}
961			return bals[i].Asset < bals[j].Asset
962		})
963	}
964	
965	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
966	func (l *Ledger) persistLocked() error {
967		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
968			return ledgerError(ErrStorage, "injected write failure")
969		}
970		return atomicWrite(l.path, l.stateView())
971	}
972	
973	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
974	func SetFailHook(l *Ledger, fw FailWriter) {
975		l.reg.failHook = fw
976	}
977

