1	// Command payflow is the 链上支付与结算编排平台 entry point.
2	package main
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/gzhysuiioo/payflow-settlement/payflow"
13	)
14	
15	func main() {
16		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
17	}
18	
19	const versionString = "payflow 0.2.0"
20	
21	func runCLI(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
22		if len(args) == 0 {
23			return runDemo(stdout)
24		}
25		switch args[0] {
26		case "demo":
27			return runDemo(stdout)
28		case "version":
29			fmt.Fprintln(stdout, versionString)
30			return 0
31		case "help", "-h", "--help":
32			usage(stdout)
33			return 0
34		case "init":
35			return cmdInit(args[1:], stdin, stdout, stderr)
36		case "submit":
37			return cmdSubmit(args[1:], stdin, stdout, stderr)
38		case "refund":
39			return cmdRefund(args[1:], stdin, stdout, stderr)
40		case "query":
41			return cmdQuery(args[1:], stdout, stderr)
42		case "reconcile":
43			return cmdReconcile(args[1:], stdin, stdout, stderr)
44		default:
45			fmt.Fprintf(stderr, "unknown command %q\n", args[0])
46			usage(stderr)
47			return 2
48		}
49	}
50	
51	func usage(w io.Writer) {
52		fmt.Fprintln(w, "usage: payflow <command> [flags]")
53		fmt.Fprintln(w, "")
54		fmt.Fprintln(w, "commands:")
55		fmt.Fprintln(w, "  init       initialize a ledger with starting balances")
56		fmt.Fprintln(w, "  submit     submit a JSON payment batch against a ledger")
57		fmt.Fprintln(w, "  refund     submit a JSON full-refund batch against a ledger")
58		fmt.Fprintln(w, "  query      print balances, settlement and refund records of a ledger")
59		fmt.Fprintln(w, "  reconcile  reconcile an ordered JSON flow against a ledger")
60		fmt.Fprintln(w, "  demo       run the in-memory settlement demo")
61		fmt.Fprintln(w, "  version    print version")
62		fmt.Fprintln(w, "  help       show this help")
63		fmt.Fprintln(w, "")
64		fmt.Fprintln(w, "ledger flags (init/submit/refund/query/reconcile):")
65		fmt.Fprintln(w, "  -l, --ledger <path>   ledger file path (required)")
66		fmt.Fprintln(w, "  -f, --file <path>     JSON input file (init/submit/refund/reconcile; default: stdin)")
67		fmt.Fprintln(w, "")
68		fmt.Fprintln(w, "reconcile range flags (seq bounds, after < seq <= through; default: full history):")
69		fmt.Fprintln(w, "  --payment-after <n>    payment seq lower bound (exclusive)")
70		fmt.Fprintln(w, "  --payment-through <n>  payment seq upper bound (inclusive)")
71		fmt.Fprintln(w, "  --refund-after <n>     refund seq lower bound (exclusive)")
72		fmt.Fprintln(w, "  --refund-through <n>   refund seq upper bound (inclusive)")
73	}
74	
75	// initRequest 是 init 的输入：{"balances":[...]}。
76	type initRequest struct {
77		Balances []payflow.BalanceInit `json:"balances"`
78	}
79	
80	type errorEnvelope struct {
81		Error struct {
82			Kind    string `json:"kind"`
83			Message string `json:"message"`
84		} `json:"error"`
85	}
86	
87	func failEnvelope(stderr io.Writer, kind, message string) int {
88		env := errorEnvelope{}
89		env.Error.Kind = kind
90		env.Error.Message = message
91		writeJSON(stderr, env)
92		return 1
93	}
94	
95	func failWithError(stderr io.Writer, err error) int {
96		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
97	}
98	
99	func writeJSON(w io.Writer, v any) {
100		data, err := json.MarshalIndent(v, "", "  ")
101		if err != nil {
102			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
103			return
104		}
105		w.Write(data)
106		w.Write([]byte("\n"))
107	}
108	
109	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
110	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
111		fs := flag.NewFlagSet(name, flag.ContinueOnError)
112		fs.SetOutput(io.Discard)
113		var ledgerPath, inputFile string
114		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
115		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
116		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
117		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
118		return fs, &ledgerPath, &inputFile
119	}
120	
121	func readInput(path string, stdin io.Reader) ([]byte, error) {
122		if path == "" {
123			return io.ReadAll(stdin)
124		}
125		return os.ReadFile(path)
126	}
127	
128	func cmdInit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
129		fs, ledgerPath, inputFile := ledgerFlagSet("init")
130		if err := fs.Parse(args); err != nil {
131			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
132		}
133		if *ledgerPath == "" {
134			return failEnvelope(stderr, payflow.ErrInvalid, "init requires --ledger <path>")
135		}
136		raw, err := readInput(*inputFile, stdin)
137		if err != nil {
138			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
139		}
140		var req initRequest
141		dec := json.NewDecoder(bytes.NewReader(raw))
142		if err := dec.Decode(&req); err != nil {
143			return failEnvelope(stderr, payflow.ErrInvalid, "parse init JSON: "+err.Error())
144		}
145		if err := requireEOF(dec, "init"); err != nil {
146			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
147		}
148		if err := payflow.CreateLedger(*ledgerPath, req.Balances); err != nil {
149			return failWithError(stderr, err)
150		}
151		writeJSON(stdout, map[string]any{
152			"status":   "initialized",
153			"ledger":   *ledgerPath,
154			"accounts": len(req.Balances),
155		})
156		return 0
157	}
158	
159	func cmdSubmit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
160		fs, ledgerPath, inputFile := ledgerFlagSet("submit")
161		if err := fs.Parse(args); err != nil {
162			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
163		}
164		if *ledgerPath == "" {
165			return failEnvelope(stderr, payflow.ErrInvalid, "submit requires --ledger <path>")
166		}
167		raw, err := readInput(*inputFile, stdin)
168		if err != nil {
169			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
170		}
171		var batch payflow.FeeBatch
172		dec := json.NewDecoder(bytes.NewReader(raw))
173		if err := dec.Decode(&batch); err != nil {
174			return failEnvelope(stderr, payflow.ErrInvalid, "parse batch JSON: "+err.Error())
175		}
176		if err := requireEOF(dec, "submit"); err != nil {
177			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
178		}
179	
180		l, err := payflow.Open(*ledgerPath)
181		if err != nil {
182			return failWithError(stderr, err)
183		}
184		defer l.Close()
185	
186		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
187		result, err := l.Submit(batch)
188		if err != nil {
189			return failWithError(stderr, err)
190		}
191		writeJSON(stdout, result)
192		return 0
193	}
194	
195	func cmdRefund(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
196		fs, ledgerPath, inputFile := ledgerFlagSet("refund")
197		if err := fs.Parse(args); err != nil {
198			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
199		}
200		if *ledgerPath == "" {
201			return failEnvelope(stderr, payflow.ErrInvalid, "refund requires --ledger <path>")
202		}
203		raw, err := readInput(*inputFile, stdin)
204		if err != nil {
205			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
206		}
207		var batch payflow.RefundBatch
208		dec := json.NewDecoder(bytes.NewReader(raw))
209		if err := dec.Decode(&batch); err != nil {
210			return failEnvelope(stderr, payflow.ErrInvalid, "parse refund batch JSON: "+err.Error())
211		}
212		if err := requireEOF(dec, "refund"); err != nil {
213			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
214		}
215	
216		l, err := payflow.Open(*ledgerPath)
217		if err != nil {
218			return failWithError(stderr, err)
219		}
220		defer l.Close()
221	
222		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
223		result, err := l.Refund(batch)
224		if err != nil {
225			return failWithError(stderr, err)
226		}
227		writeJSON(stdout, result)
228		return 0
229	}
230	
231	func cmdQuery(args []string, stdout, stderr io.Writer) int {
232		fs, ledgerPath, _ := ledgerFlagSet("query")
233		if err := fs.Parse(args); err != nil {
234			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
235		}
236		if *ledgerPath == "" {
237			return failEnvelope(stderr, payflow.ErrInvalid, "query requires --ledger <path>")
238		}
239		l, err := payflow.Open(*ledgerPath)
240		if err != nil {
241			return failWithError(stderr, err)
242		}
243		defer l.Close()
244		snap, err := l.Query()
245		if err != nil {
246			return failWithError(stderr, err)
247		}
248		writeJSON(stdout, snap)
249		return 0
250	}
251	
252	func cmdReconcile(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
253		fs, ledgerPath, inputFile := ledgerFlagSet("reconcile")
254		// 序号边界：after 排除下界、through 包含上界（after < seq <= through）。
255		// 用指针区分“未提供”与显式给出的 0：未提供时由库取缺省值（下界 0、
256		// 上界为该类记录的最大成功序号）。
257		var paymentAfter, paymentThrough, refundAfter, refundThrough int64
258		fs.Int64Var(&paymentAfter, "payment-after", 0, "payment seq lower bound (exclusive)")
259		fs.Int64Var(&paymentThrough, "payment-through", 0, "payment seq upper bound (inclusive)")
260		fs.Int64Var(&refundAfter, "refund-after", 0, "refund seq lower bound (exclusive)")
261		fs.Int64Var(&refundThrough, "refund-through", 0, "refund seq upper bound (inclusive)")
262		if err := fs.Parse(args); err != nil {
263			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
264		}
265		if *ledgerPath == "" {
266			return failEnvelope(stderr, payflow.ErrInvalid, "reconcile requires --ledger <path>")
267		}
268		raw, err := readInput(*inputFile, stdin)
269		if err != nil {
270			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
271		}
272		// 先严格解析全部输入：任一条目不合法则整次拒绝，退出码 1，不输出部分报告。
273		entries, err := payflow.ParseReconcileRequest(raw)
274		if err != nil {
275			return failWithError(stderr, err)
276		}
277	
278		bounds := payflow.ReconcileBounds{}
279		fs.Visit(func(f *flag.Flag) {
280			switch f.Name {
281			case "payment-after":
282				v := paymentAfter
283				bounds.PaymentAfter = &v
284			case "payment-through":
285				v := paymentThrough
286				bounds.PaymentThrough = &v
287			case "refund-after":
288				v := refundAfter
289				bounds.RefundAfter = &v
290			case "refund-through":
291				v := refundThrough
292				bounds.RefundThrough = &v
293			}
294		})
295	
296		l, err := payflow.Open(*ledgerPath)
297		if err != nil {
298			return failWithError(stderr, err)
299		}
300		defer l.Close()
301	
302		// 对账只读：不改余额、历史或账本文件。边界非法同样整次拒绝、不输出部分
303		// 报告；输入有差异仍是正常结果，退出码 0。
304		report, err := l.ReconcileFlowRanged(entries, bounds)
305		if err != nil {
306			return failWithError(stderr, err)
307		}
308		writeJSON(stdout, report)
309		return 0
310	}
311	
312	// requireEOF 拒绝 JSON 文档之后的尾随内容。
313	func requireEOF(dec *json.Decoder, what string) error {
314		if tok, err := dec.Token(); err != io.EOF {
315			if err == nil {
316				return fmt.Errorf("%s: unexpected trailing content after JSON document (token %v)", what, tok)
317			}
318			return fmt.Errorf("%s: %v", what, err)
319		}
320		return nil
321	}
322	
323	func runDemo(stdout io.Writer) int {
324		intents := []payflow.Intent{
325			{ID: "pay-1", Account: "aa-1", Paymaster: "pm-1", Amount: 1500, Asset: "usdc", Nonce: 1, State: "pending"},
326			{ID: "pay-2", Account: "aa-1", Paymaster: "pm-1", Amount: 900, Asset: "usdc", Nonce: 2, State: "pending"},
327		}
328		spent := map[string]bool{}
329		var settlements []payflow.Settlement
330		for _, intent := range intents {
331			settlement := payflow.Execute(intent, 30, spent, 2000)
332			settlements = append(settlements, settlement)
333			fmt.Fprintf(stdout, "intent=%s status=%s charged=%d reason=%s\n", settlement.Intent, settlement.Status, settlement.Charged, settlement.Reason)
334		}
335		duplicate := payflow.Execute(intents[0], 30, spent, 2000)
336		fmt.Fprintf(stdout, "duplicate of %s status=%s reason=%s\n", duplicate.Intent, duplicate.Status, duplicate.Reason)
337		fmt.Fprintln(stdout, "reconciliation gaps:", payflow.Reconcile(intents, settlements))
338		return 0
339	}
