342		}
343		// 差额方向为流水减账本。
344		if d := findDiff("aa-1", "usdc"); d.NetChargedDiff != "503" || d.LedgerNetCharged != "0" || d.FlowNetCharged != "503" {
345			t.Fatalf("usdc diff=%+v", d)
