617			{ID: "p2", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(2000), Nonce: 2, State: "pending"},
618			{ID: "p3", Account: "aa-2", Asset: "eth", Amount: i64p(10), State: "pending"},
619		}})
620		if err != nil {
621			t.Fatalf("submit: %v", err)
622		}
623		for i, want := range []string{StatusSettled, StatusSettled, StatusSettled} {
624			if res.Results[i].Status != want {
625				t.Fatalf("setup payment %d status=%s", i, res.Results[i].Status)
626			}
627		}
628		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
629			{ID: "r1", SettlementID: "p1", Reason: "cancel"},
630			{ID: "r2", SettlementID: "p2", Reason: "cancel"},
631		}})
632		if err != nil {
633			t.Fatalf("refund: %v", err)
634		}
635		for i, want := range []string{StatusRefundSuccess, StatusRefundSuccess} {
636			if rr.Results[i].Status != want {
637				t.Fatalf("setup refund %d status=%s", i, rr.Results[i].Status)
638			}
