	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer l2.Close()
	rq, err := l2.Query()
	if err != nil {
		t.Fatalf("query reopened: %v", err)
	}
	rj, _ := json.Marshal(rq)
	if string(rj) != string(aj) {
		t.Fatalf("ledger file changed by reconcile:\ndisk=%s\nmem =%s", rj, aj)
	}
}

