1224				mu.Unlock()
1225			}()
1226		}
1227		wg.Wait()
1228		if c[StatusSettled] != 1 || c[StatusFunds] != n-1 {
1229			t.Fatalf("counts=%v want exactly 1 settled", c)
1230		}
