1241		goodRF := RefundRecord{ID: "r1", SettlementID: "p1", Reason: "x", Account: "aa", Asset: "usdc", Amount: 300, Fee: 0, Charged: 300, AfterSeq: 1, Seq: 1}
1242		finalBack := map[balanceKey]int64{k: 1000} // 退完回到初始
1243	
1244		mkRF := func(mut func(*RefundRecord)) []RefundRecord {
1245			r := goodRF
1246			mut(&r)
1247			return []RefundRecord{r}
1248		}
1249	
1250		cases := map[string]struct {
1251			final   map[balanceKey]int64
1252			records []Record
1253			refunds []RefundRecord
1254		}{
1255			"missing settlement": {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.SettlementID = "ghost" })},
1256			"double refund": {finalBack, []Record{rec}, []RefundRecord{
1257				goodRF,
1258				func() RefundRecord { r := goodRF; r.ID = "r2"; r.Seq = 2; return r }(),
1259			}},
1260			"amount differs":      {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Amount = 299; r.Charged = 299 })},
1261			"charged differs":     {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Charged = 301 })},
1262			"asset differs":       {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Asset = "eth" })},
1263			"empty reason":        {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Reason = "" })},
1264			"seq gap":             {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Seq = 2 })},
1265			"after_seq too large": {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.AfterSeq = 2 })},
1266			"balance mismatch":    {map[balanceKey]int64{k: 999}, []Record{rec}, mkRF(func(r *RefundRecord) {})},
1267		}
1268	
1269		// “duplicate refund id”：两笔不同结算各退一次，但两条退款记录共用编号 r1。
1270		rec2 := Record{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 1, Nonce: 2, FeeBps: 0, Fee: 0, Charged: 1, Seq: 2}
1271		rf2 := goodRF
1272		rf2.Seq = 2
1273		rf2.SettlementID = "p2"
1274		rf2.Amount, rf2.Fee, rf2.Charged = 1, 0, 1
1275		rf2.AfterSeq = 2
1276		cases["duplicate refund id"] = struct {
1277			final   map[balanceKey]int64
1278			records []Record
1279			refunds []RefundRecord
1280		}{
1281			final:   map[balanceKey]int64{k: 1000 - 1},
1282			records: []Record{rec, rec2},
1283			refunds: []RefundRecord{goodRF, rf2},
1284		}
1285	
1286		for name, tc := range cases {
1287			t.Run(name, func(t *testing.T) {
1288				if err := validateAndReplay(initial, tc.final, tc.records, tc.refunds); err == nil || KindOf(err) != ErrCorrupt {
1289					t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
1290				}
1291			})
1292		}
1293	
