1309	// 读取与仅付款都不改写文件（保持无 refunds 键），首次退款才引入该字段。
1310	func TestLegacyFileWithoutRefundsField(t *testing.T) {
1311		// 按磁盘文档规范字段顺序构造一个带合法 checksum 的旧版文档。
1312		legacy := func(balance int64, records ...Record) []byte {
1313			type doc struct {
1314				Version     int           `json:"version"`
1315				Initial     []BalanceView `json:"initial_balances"`
1316				Balances    []BalanceView `json:"balances"`
1317				Settlements []Record      `json:"settlements"`
1318			}
1319			d := doc{
1320				Version:     1,
1321				Initial:     []BalanceView{{Account: "aa", Asset: "usdc", Balance: 1000}},
1322				Balances:    []BalanceView{{Account: "aa", Asset: "usdc", Balance: balance}},
1323				Settlements: records,
1324			}
1325			payload, err := json.Marshal(d)
1326			if err != nil {
1327				t.Fatal(err)
1328			}
1329			sum := checksumHex(payload)
1330			return append(append(payload[:len(payload)-1], []byte(`,"checksum":"`+sum+`"}`)...), '\n')
1331		}
1332		rec := Record{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 300, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 300, Seq: 1}
1333		path := filepath.Join(t.TempDir(), "old.json")
1334		if err := os.WriteFile(path, legacy(700, rec), 0o600); err != nil {
1335			t.Fatal(err)
1336		}
1337	
1338		l := openOrFail(t, path)
1339		snap, err := l.Query()
1340		if err != nil {
1341			t.Fatalf("query legacy: %v", err)
1342		}
1343		if len(snap.Refunds) != 0 || snap.Balances[0].Balance != 700 {
1344			t.Fatalf("legacy query: %+v", snap)
1345		}
1346	
1347		// 再付款一笔：无退款，文件必须保持不含 refunds 键。
1348		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p2", "aa", "usdc", 100)}}); err != nil {
1349			t.Fatal(err)
1350		}
1351		if data, _ := os.ReadFile(path); bytes.Contains(data, []byte(`"refunds"`)) {
1352			t.Fatalf("submit on refund-less ledger must not add refunds key:\n%s", data)
1353		}
1354	
1355		// 首次退款引入 refunds 键并全额回到 900（700-100+300）。
1356		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "legacy")}})
1357		if err != nil {
1358			t.Fatal(err)
1359		}
1360		if rr.Results[0].Status != StatusRefundSuccess || rr.Results[0].Charged != 300 {
1361			t.Fatalf("legacy refund: %+v", rr.Results[0])
1362		}
1363		data, _ := os.ReadFile(path)
1364		if !bytes.Contains(data, []byte(`"refunds"`)) {
1365			t.Fatalf("refund must persist refunds key:\n%s", data)
1366		}
1367		if bal, _ := l.Balance("aa", "usdc"); bal != 900 {
1368			t.Fatalf("balance after legacy refund=%d want 900", bal)
1369		}
1370	
1371		// 关闭重开（新进程语义）应正常恢复付款→退款→付款账本。
1372		if err := l.Close(); err != nil {
1373			t.Fatal(err)
1374		}
1375		l2 := openOrFail(t, path)
1376		snap2, _ := l2.Query()
1377		if len(snap2.Settlements) != 2 || len(snap2.Refunds) != 1 {
1378			t.Fatalf("reopen legacy: %+v", snap2)
1379		}
1380		if bal, _ := l2.Balance("aa", "usdc"); bal != 900 {
1381			t.Fatalf("reopen balance=%d want 900", bal)
1382		}
1383	}
