1605		if res.Results[0].Status != StatusDuplicate {
1606			t.Fatalf("limits must not affect idempotency: %+v", res.Results[0])
1607		}
1608	
1609		// 额度按提交从零计算：新批次同样的上限可再扣 100，历史扣款不占额度。
1610		res, err = l.Submit(FeeBatch{
1611			FeeBps:  0,
1612			Limits:  []ChargeLimit{limit("aa", "usdc", 100)},
1613			Intents: []PaymentIntent{intent("p2", "aa", "usdc", 100)},
1614		})
