1631		}
1632		want := []string{StatusSettled, StatusLimitExceeded}
1633		if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
1634			t.Fatalf("refund must not restore quota: %v want %v", got, want)
1635		}
1636	}
1637	
1638	func TestChargeLimitOverflowSafety(t *testing.T) {
1639		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: math.MaxInt64}})
1640		l := openOrFail(t, path)
