1662	func TestChargeLimitStorageFailureRestoresQuota(t *testing.T) {
1663		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 10000}})
1664		l := openOrFail(t, path)
