1671			Intents: []PaymentIntent{
1672				intent("ok1", "aa", "usdc", 100), // 成功，已用 100
1673				intent("boom", "aa", "usdc", 50), // 保存失败：回滚且不占额度
1674				intent("ok2", "aa", "usdc", 100), // 恰好用满 200
1675			},
